do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$PONY$q$,$q$Pony.ai$q$,null,null,true,false,array[$q$US$q$,$q$HKEX$q$]::text[],$q$Nasdaq; HKEX 2026$q$,$q$CN$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$ATBB$q$,$q$private_company$q$),($q$Alipay$q$,$q$private_company$q$),($q$Amap$q$,$q$private_company$q$),($q$BAIC$q$,$q$public_company$q$),($q$Cainiao$q$,$q$private_company$q$),($q$Cyantron$q$,$q$private_company$q$),($q$Cyantron Logistics Technology Co., Ltd.$q$,$q$private_company$q$),($q$GAC$q$,$q$public_company$q$),($q$GTMC$q$,$q$private_company$q$),($q$HongShan$q$,$q$private_company$q$),($q$Meituan$q$,$q$public_company$q$),($q$NVIDIA$q$,$q$public_company$q$),($q$NavInfo$q$,$q$public_company$q$),($q$Neolix$q$,$q$private_company$q$),($q$OnTime Mobility$q$,$q$private_company$q$),($q$Roads and Transport Authority in Dubai$q$,$q$institution$q$),($q$SAIC$q$,$q$public_company$q$),($q$SAIC Motor$q$,$q$public_company$q$),($q$SANY$q$,$q$public_company$q$),($q$Sinotrans$q$,$q$public_company$q$),($q$Sunlight Mobility$q$,$q$private_company$q$),($q$Tencent$q$,$q$public_company$q$),($q$Toyota$q$,$q$public_company$q$),($q$Uber$q$,$q$public_company$q$),($q$Xianli$q$,$q$private_company$q$),($q$Zhuifeng Intelligent$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Additionally, we also generated revenues of US$0.6 million, US$0.1 million and US$0.1 million, respectively, for the years ended December 31, 2023, 2024 and 2025 from Toyota, a leading OEM and our strategic investor and related party, representing 0.8%, 0.1% and 0.1% of our total revenues for the same periods, respectively.$q$),(2,$q$As another firm step towards commercial applications of our robotruck services, we entered into a strategic partnership with SANY, a leading truck manufacturer in China, in May 2022, pursuant to which we will co-develop automotive-grade Level 4 trucks powered by our technology.$q$),(3,$q$As part of our strategic cooperation agreement, we are responsible for licensing our autonomous driving technology and providing technical support for the development of robotrucks, and SANY has agreed to, among other things, manufacture robotrucks at arm’s length prices, and help to market our robotrucks through its sales channels.$q$),(4,$q$Concurrently in Beijing, our January partnership with Beijing ATBB Travel & Express Service Co., Ltd. (“ATBB”) expands our footprint into premium business travel, successfully penetrating higher-value mobility segments.$q$),(5,$q$Cyantron offers paid transportation services to Sinotrans to fulfill its freight orders across China with a fleet of robotrucks, consisting of both Level 2++ intelligent trucks and Level 4 autonomous trucks with safety drivers.$q$),(6,$q$Entities affiliated with HongShan (4) 22,615,083 — 5.2 % 1.9 %$q$),(7,$q$For example, our latest computing unit is built on NVIDIA DRIVE Orin, an automotive-grade processor purpose-built for Level 4 autonomous vehicles, for high performance and scalable compute.$q$),(8,$q$For example, with strategic investments in OnTime Mobility in April 2022, OnTime Mobility owned and operated a fleet of 50 vehicles integrated with our Virtual Driver on its mobile app to offer paid public-facing robotaxi services in Guangzhou and Shenzhen, China.$q$),(9,$q$For the years ended December 31, 2023, 2024 and 2025, we generated revenue of US$22.5 million, US$30.7 million and US$29.6 million, respectively, from transportation service fees paid by Sinotrans to Cyantron Group, representing 31.3%, 40.9% and 32.9% of our total revenues for the same periods, respectively.$q$),(10,$q$In 2025, we formed a partnership with Sunlight Mobility, further broadening our downstream deployment network and supporting fleet rollout in a wider range of operating scenarios.$q$),(11,$q$In July 2025, we announced our robotaxi deployment plan in collaboration with the Roads and Transport Authority in Dubai, representing a key step toward entering the Middle East market.$q$),(12,$q$In May 2025, we announced a strategic partnership with Uber to deploy our robotaxis onto the Uber platform, marking a key step toward integrating our autonomous mobility solutions into global ride-hailing ecosystems and expanding into international markets.$q$),(13,$q$In addition, we have formed partnerships with established TNCs, such as Alipay, Amap and OnTime Mobility to scale and expand our robotaxi services and enhance passenger coverage.$q$),(14,$q$In addition, we have partnered with other leading OEMs, such as BAIC, GAC and SAIC, to leverage their mature supply chain and after-sales network and jointly deploy vehicles in the overseas markets.$q$),(15,$q$In the short term, Cyantron offers hybrid logistics capacity, including its robotruck services, to Sinotrans for logistics fees.$q$),(16,$q$Licensing and applications : we have co-development collaborations with logistics customers, such as Meituan, Neolix and Cainiao, on hardware components, and with NVIDIA.$q$),(17,$q$Name of Service Provider Background Information Principal Services Procured by Pony Fee Terms Amap ​ A leading domestic digital map, navigation, and location service provide ​ Real-time maps and transit information on the  PonyPilot  mobile app and web page ​ One-time fixed service fees for the entire contract term NavInfo ​ A top-tier domestic supplier of integrated solutions for smart mobility applications ​ Provision of high-definition digital maps ​ One-time fixed service fees for the entire contract term Xianli ​ A leading domestic supplier of data annotation services for autonomous driving and other commercial applications ​ The collection and handling of mapping and surveying related data ​ Service fees determined based on factors including the data quantities and complexity of deliverables and outputs ​$q$),(18,$q$Our strategic partner and related party, Sinotrans, is China’s largest freight logistics company, according to CIFA.$q$),(19,$q$Robotaxi services : we have strategically built in-depth collaborations with trusted OEMs such as Toyota, BAIC, GAC and SAIC Motor to co-develop and mass-produce Level 4 autonomous vehicles.$q$),(20,$q$Robotruck services. Our revenues generated from robotruck services increased slightly by 0.6 % from US$40.4 million in 2024 to US$ 40.6  million in 2025, mainly contributed by our deepened collaboration with Sinotrans to continuously enhance fleet operations.$q$),(21,$q$Shareholders of Cyantron Logistics Technology Co., Ltd. are Beijing (HX) Pony and Sinotrans, each holding 51.0% and 49.0% of its equity interests, respectively.$q$),(22,$q$Sinotrans partnership . In December 2021, we announced our partnership with Sinotrans, China’s largest freight logistics comp$q$),(23,$q$TMC (trade nature) 5 ​ 7 Sinotrans (trade nature) 8,317 ​ 10,153 Zhuifeng Intelligent (trade nature) — ​ 1,178 Total 8,322 ​ 11,338$q$),(24,$q$Through our collaboration with Toyota, we successfully launched our 6th generation Level 4 autonomous vehicle model in January 2022 to support fully driverless Level 4 robotaxi operations.$q$),(25,$q$Through our partnership with Sinotrans, we have formed a robotruck fleet that provides routine transportation services to clients.$q$),(26,$q$Toyota Motor Corporation (3) 42,453,831 — 9.8 % 3.6 %$q$),(27,$q$Toyota Motor Corporation (“TMC”) ​ Shareholder of the Group$q$),(28,$q$Under the terms of the joint venture agreement, Toyota will supply the joint venture, acting as a fleet company, with Toyota-branded battery electric vehicles.$q$),(29,$q$We also continued to deepen integration with Tencent’s WeChat Mobility Services platform in Shenzhen and Guangzhou, enhancing service connectivity and user access through established mobility platforms.$q$),(30,$q$We elevated our collaboration with OnTime Mobility in Guangzhou to scale our Robotaxi fleet and secure recurring licensing revenues.$q$),(31,$q$We formed Cyantron as its controlling shareholder to build a mixed capacity freight service provider with our autonomous driving technology.$q$),(32,$q$We have conducted transactions with Zhuifeng Intelligent, one of our equity method investees, in the ordinary course of our business.$q$),(33,$q$We have formed a joint venture with Toyota and GTMC to advance the mass production and large-scale deployment of fully driverless robotaxis in China under the joint deployment model.$q$),(34,$q$We have rendered engineering solution services to TMC in exchange for service fees of US$0.6 million in 2023, US$0.1 million in 2024 and US$ 0.1  million in 2025.$q$),(35,$q$We offered engineering solutions services to Zhuifeng Intelligent in exchange for service fees of nil in 2023, nil in 2024 and US$ 1.1  million in 2025.$q$),(36,$q$We offered virtual driver operation and other related services to Sinotrans in exchange for services fees of approximately US$22.5 million in 2023, US$30.7 million in 2024 and US$ 29.6  million in 2025.$q$),(37,$q$Zhuifeng Intelligent Technology (Guangzhou) Co., Ltd (“Zhuifeng Intelligent”) ​ Equity method investee$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$invests$q$,$q$Sinotrans$q$,$q$PONY$q$,$q${21}$q$::int[],$q${blk11}$q$::text[],49.0,$q$exact$q$,$q$ownership$q$,null),(2,$q$partners$q$,$q$PONY$q$,$q$Sinotrans$q$,$q${18,22,25,20}$q$::int[],$q${blk19,blk84,blk85,blk111}$q$::text[],null,null,null,null),(3,$q$sells_to$q$,$q$PONY$q$,$q$Sinotrans$q$,$q${9,15,5,36,23}$q$::int[],$q${blk19,blk85,blk112,blk124,blk165}$q$::text[],32.9,$q$exact$q$,$q$source_revenue$q$,null),(4,$q$sells_to$q$,$q$PONY$q$,$q$Toyota$q$,$q${1,34,23}$q$::int[],$q${blk19,blk124,blk165}$q$::text[],0.1,$q$exact$q$,$q$source_revenue$q$,null),(5,$q$invests$q$,$q$Toyota$q$,$q$PONY$q$,$q${1,26,27}$q$::int[],$q${blk19,blk122,blk165}$q$::text[],null,null,null,null),(6,$q$partners$q$,$q$PONY$q$,$q$Toyota$q$,$q${33,24}$q$::int[],$q${blk74,blk86}$q$::text[],null,null,null,null),(7,$q$partners$q$,$q$PONY$q$,$q$GTMC$q$,$q${33}$q$::int[],$q${blk74}$q$::text[],null,null,null,null),(8,$q$partners$q$,$q$PONY$q$,$q$BAIC$q$,$q${14,19}$q$::int[],$q${blk74,blk86}$q$::text[],null,null,null,null),(9,$q$partners$q$,$q$PONY$q$,$q$GAC$q$,$q${14,19}$q$::int[],$q${blk74,blk86}$q$::text[],null,null,null,null),(10,$q$partners$q$,$q$PONY$q$,$q$SAIC$q$,$q${14}$q$::int[],$q${blk74}$q$::text[],null,null,null,null),(11,$q$partners$q$,$q$PONY$q$,$q$Uber$q$,$q${12}$q$::int[],$q${blk74}$q$::text[],null,null,null,null),(12,$q$partners$q$,$q$PONY$q$,$q$Roads and Transport Authority in Dubai$q$,$q${11}$q$::int[],$q${blk74}$q$::text[],null,null,null,null),(13,$q$supplies$q$,$q$NVIDIA$q$,$q$PONY$q$,$q${7}$q$::int[],$q${blk80}$q$::text[],null,null,null,null),(14,$q$supplies$q$,$q$Toyota$q$,$q$PONY$q$,$q${28}$q$::int[],$q${blk84}$q$::text[],null,null,null,null),(15,$q$partners$q$,$q$PONY$q$,$q$Sunlight Mobility$q$,$q${10}$q$::int[],$q${blk84}$q$::text[],null,null,null,null),(16,$q$partners$q$,$q$PONY$q$,$q$OnTime Mobility$q$,$q${30,13}$q$::int[],$q${blk84,blk86}$q$::text[],null,null,null,null),(17,$q$partners$q$,$q$PONY$q$,$q$ATBB$q$,$q${4}$q$::int[],$q${blk84}$q$::text[],null,null,null,null),(18,$q$partners$q$,$q$PONY$q$,$q$Tencent$q$,$q${29}$q$::int[],$q${blk84}$q$::text[],null,null,null,null),(19,$q$invests$q$,$q$PONY$q$,$q$Cyantron$q$,$q${31}$q$::int[],$q${blk85}$q$::text[],null,null,null,null),(20,$q$partners$q$,$q$PONY$q$,$q$SANY$q$,$q${2}$q$::int[],$q${blk85}$q$::text[],null,null,null,null),(21,$q$supplies$q$,$q$SANY$q$,$q$PONY$q$,$q${3}$q$::int[],$q${blk85}$q$::text[],null,null,null,null),(22,$q$partners$q$,$q$PONY$q$,$q$SAIC Motor$q$,$q${19}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(23,$q$partners$q$,$q$PONY$q$,$q$Alipay$q$,$q${13}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(24,$q$partners$q$,$q$PONY$q$,$q$Amap$q$,$q${13}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(25,$q$invests$q$,$q$PONY$q$,$q$OnTime Mobility$q$,$q${8}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(26,$q$partners$q$,$q$PONY$q$,$q$Meituan$q$,$q${16}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(27,$q$partners$q$,$q$PONY$q$,$q$Neolix$q$,$q${16}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(28,$q$partners$q$,$q$PONY$q$,$q$Cainiao$q$,$q${16}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(29,$q$partners$q$,$q$PONY$q$,$q$NVIDIA$q$,$q${16}$q$::int[],$q${blk86}$q$::text[],null,null,null,null),(30,$q$supplies$q$,$q$Amap$q$,$q$PONY$q$,$q${17}$q$::int[],$q${blk92}$q$::text[],null,null,null,null),(31,$q$supplies$q$,$q$NavInfo$q$,$q$PONY$q$,$q${17}$q$::int[],$q${blk92}$q$::text[],null,null,null,null),(32,$q$supplies$q$,$q$Xianli$q$,$q$PONY$q$,$q${17}$q$::int[],$q${blk92}$q$::text[],null,null,null,null),(33,$q$invests$q$,$q$Sinotrans$q$,$q$Cyantron Logistics Technology Co., Ltd.$q$,$q${21}$q$::int[],$q${blk11}$q$::text[],49.0,$q$exact$q$,$q$ownership$q$,null),(34,$q$invests$q$,$q$HongShan$q$,$q$PONY$q$,$q${6}$q$::int[],$q${blk122}$q$::text[],5.2,$q$approximate$q$,$q$ownership$q$,null),(35,$q$sells_to$q$,$q$PONY$q$,$q$Zhuifeng Intelligent$q$,$q${35,23}$q$::int[],$q${blk124,blk165}$q$::text[],null,null,nu